const PHASES = ["DISTANCE", "CLINCH", "TAKEDOWN", "SOL", "SOUMISSION",
                "KNOCKDOWN", "KO", "TKO", "FIN"];

const ZONES = { t: "tete", c: "corps", j: "jambes" };

