    seuil: 48, cout: "exigence", coutNon: "exigence", duree: 120,
    oui: (n) => `« ${n} ? … Ça peut se vendre. Je vais voir son camp. »`,
    non: (n) => `« ${n} a d'autres plans. Et toi, tu n'as pas encore le poids pour choisir. »`,
